insert into public.scenarios (id,code,title,prologue_script,final_venue) values ('SCENARIO_CRIMINAL','SCENARIO_CRIMINAL','사라진 판매자, 남겨진 벽돌','["세 달 동안 모은 용돈으로 중고 게임기를 샀다. 드디어 택배가 도착했다!","잠깐… 게임기 대신 붉은 벽돌이 들어 있잖아?!","“탈퇴한 사용자입니다.” 판매자와의 대화는 끊겼다. 하지만 기록과 법전은 남아 있다."]','경찰서 사이버수사팀') on conflict (id) do nothing;
