insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CRIMINAL-a','SCENARIO_CRIMINAL','택배 송장 사본','원본과 취득 경위를 함께 보관한 사건 자료입니다.','true','SCENARIO_CRIMINAL-c') on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CRIMINAL-b','SCENARIO_CRIMINAL','판매자 채팅 캡처','당사자가 적법하게 제공받은 기록입니다. 다른 자료와 비교해 보세요.','true','SCENARIO_CRIMINAL-c') on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CRIMINAL-c','SCENARIO_CRIMINAL','발송지 모순 입증 보고서','두 원본의 날짜·내용을 대조한 정리 자료. 원본을 함께 제출합니다. 합성 자체가 법적 효력을 보장하지는 않습니다.','true',null) on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CRIMINAL-d','SCENARIO_CRIMINAL','대금 이체 내역','하루 본인 계좌에서 판매자 계좌로 대금을 보낸 거래내역입니다. 직접 조회해 얻은 자료입니다.','true',null) on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CRIMINAL-e','SCENARIO_CRIMINAL','벽돌이 든 택배 상자 사진','개봉 직후 상자 속 벽돌을 직접 촬영한 사진. 파손이 아니라 처음부터 들어 있던 물건임을 보여 줍니다.','true',null) on conflict (id) do nothing;
