insert into public.scenarios (id,code,title,prologue_script,final_venue) values ('SCENARIO_LABOR','SCENARIO_LABOR','내가 일한 시간은 사라지지 않아','["주 20시간씩 꼬박 출근한 편의점. 오늘도 야간 교대를 마쳤다.","“내일부터 나오지 마. 주휴수당? 학생한테 그런 게 어딨어!”","상시 5인 이상 사업장, 4주 평균 주 20시간 소정근로와 개근. 내 기록과 노동법 책자를 확인하자."]','지방노동위원회') on conflict (id) do nothing;
