insert into public.scenarios (id,code,title,prologue_script,final_venue) values ('SCENARIO_CIVIL_CONTRACT','SCENARIO_CIVIL_CONTRACT','환불 불가라는 말 뒤에','["부모님 동의 없이 80만 원짜리 한정판 굿즈 계약을 했다.","“한번 사면 환불 불가야.” 아직 물건을 받지도 못했는데…","처분을 허락받은 용돈 범위를 넘는 계약. 취소할 수 있을까? 민법 책을 펼쳐 보자."]','간이조정실') on conflict (id) do nothing;
