insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-a','SCENARIO_CIVIL_CONTRACT','법정대리인 동의 부재 자료','원본과 취득 경위를 함께 보관한 사건 자료입니다.','true','SCENARIO_CIVIL_CONTRACT-c') on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-b','SCENARIO_CIVIL_CONTRACT','내용증명 발송 사본','당사자가 적법하게 제공받은 기록입니다. 다른 자료와 비교해 보세요.','true','SCENARIO_CIVIL_CONTRACT-c') on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-c','SCENARIO_CIVIL_CONTRACT','계약 취소 통지 자료집','두 원본의 날짜·내용을 대조한 정리 자료. 원본을 함께 제출합니다. 합성 자체가 법적 효력을 보장하지는 않습니다.','true',null) on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-d','SCENARIO_CIVIL_CONTRACT','생년월일 확인 자료','하루 본인이 직접 발급한 주민등록 기준 생년월일 확인 자료. 만 16세로 만 19세 미만입니다.','true',null) on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-e','SCENARIO_CIVIL_CONTRACT','용돈 허락 범위 확인서','부모님이 허락한 용돈의 범위(월 5만 원)를 적어 둔 용돈 기입장 기록입니다.','true',null) on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-f','SCENARIO_CIVIL_CONTRACT','주문 대화 기록','주문 당시 판매점과 나눈 대화. 하루가 나이를 밝힌 내용과 이후 계약을 인정한 적 없다는 점이 담겨 있습니다.','true',null) on conflict (id) do nothing;
insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CIVIL_CONTRACT-g','SCENARIO_CIVIL_CONTRACT','환불 불가 약관 캡처','매장에 붙은 “한번 사면 환불 불가” 문구를 찍은 사진. 판매점이 정한 거래 조건일 뿐입니다.','true',null) on conflict (id) do nothing;
