insert into public.scenarios (id,code,title,prologue_script,final_venue) values ('SCENARIO_CONSTITUTIONAL','SCENARIO_CONSTITUTIONAL','자정이 되면 사라지는 나의 선택','["가상 세계에 새 모바일 셧다운법이 생겼다. 실제 현행 제도와는 다른 이야기다.","자정. 게임 화면이 멈추고 “청소년 이용 제한”이라는 글자가 나타났다.","모든 청소년을 일괄 제한하는 것이 꼭 필요할까? 헌법 조문과 자료로 따져 보자."]','헌법재판소 대심판정') on conflict (id) do nothing;
