insert into public.clues_master (id,scenario_id,title,description,is_admissible,synth_target_id) values ('SCENARIO_CONSTITUTIONAL-d','SCENARIO_CONSTITUTIONAL','법안 제안이유서','국회 법안 열람대에서 열람한 제안이유서. 청소년의 수면 확보와 건강 보호를 입법 목적으로 밝힙니다.','true',null) on conflict (id) do nothing;
